  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.offer-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 780px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0;
}

.section-head p,
.muted {
  color: #516070;
  line-height: 1.6;
}

.offer-tabs {
  display: inline-flex;
  gap: 0.5rem;
  background: rgba(8, 38, 58, 0.06);
  border-radius: 999px;
  padding: 0.35rem;
  margin: 1rem 0;
}

.offer-tabs button {
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0.7rem 1.1rem;
  color: #08263a;
  font-weight: 800;
  cursor: pointer;
}

.offer-tabs button.active {
  background: #fff;
  box-shadow: 0 8px 22px rgba(8, 38, 58, 0.08);
}

.offer-tabs span {
  display: inline-flex;
  min-width: 1.6rem;
  height: 1.6rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.16);
  color: #b58b4a;
  margin-left: 0.35rem;
}

.offer-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  align-items: end;
  margin: 1rem 0 1.4rem;
}

.offer-toolbar label {
  display: grid;
  gap: 0.35rem;
  color: #08263a;
  font-weight: 700;
  min-width: 260px;
}

.offer-toolbar input {
  min-height: 42px;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.65rem 0.75rem;
  background: #fff;
  font: inherit;
}

.offer-list {
  display: grid;
  gap: 1rem;
}

.offer-card,
.empty-card {
  background: #fff;
  border-radius: 24px;
  padding: 1.25rem;
  border: 1px solid rgba(8, 38, 58, 0.08);
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
}

.offer-card {
  cursor: pointer;
}

.offer-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 22px 55px rgba(8, 38, 58, 0.12);
}

.offer-top {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
}

.status-pill {
  display: inline-flex;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 800;
}

.status-accepted {
  background: rgba(4, 120, 87, 0.12);
  color: #047857;
}

.status-declined,
.status-expired {
  background: rgba(185, 28, 28, 0.1);
  color: #b91c1c;
}

.validity {
  color: #516070;
  font-size: 0.9rem;
}

.offer-card h2 {
  margin: 1rem 0 0.35rem;
  color: #08263a;
}

.offer-date,
.offer-message {
  color: #516070;
  line-height: 1.5;
}

.offer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 0.75rem;
  margin: 1rem 0;
}

.offer-grid div {
  display: grid;
  gap: 0.25rem;
  background: #f8f5ef;
  border-radius: 16px;
  padding: 0.9rem;
}

.offer-grid strong {
  color: #08263a;
}

.offer-grid span {
  color: #516070;
  font-weight: 700;
}

.offer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1rem;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 0.7rem 1rem;
  font-weight: 800;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.error-message {
  color: #b91c1c;
}

@media (max-width: 640px) {
  .offer-tabs {
    width: 100%;
    overflow: auto;
  }
  .offer-toolbar label {
    min-width: 100%;
  }
}
.offer-origin {
  margin: 0.35rem 0 0.75rem;
  font-size: 0.85rem;
  font-weight: 700;
  color: #64748b;
}

.request-card {
  border-color: rgba(242, 140, 40, 0.28);
  background: #fffaf3;
}

.request-edit-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  margin-top: 18px;
  padding: 18px;
  border: 1px solid rgba(11, 75, 90, 0.16);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
}

.request-edit-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-weight: 700;
  color: #0b2f44;
}

.request-edit-form input,
.request-edit-form textarea {
  border: 1px solid rgba(11, 75, 90, 0.18);
  border-radius: 12px;
  padding: 10px 12px;
  font: inherit;
  background: #fff;
}

.request-edit-form .wide {
  grid-column: 1/-1;
}

.success-message {
  padding: 12px 16px;
  border-radius: 14px;
  background: rgba(22, 163, 74, 0.12);
  color: #166534;
  font-weight: 700;
}

.offer-page-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.create-offer-request-btn {
  white-space: nowrap;
}

@media (max-width: 720px) {
  .offer-page-head {
    flex-direction: column;
  }
  .create-offer-request-btn {
    width: 100%;
  }
